# -*- coding: utf-8 -*-
"""
SpikeGatedMixer – Dual-Stream Spike-Controlled Feature Mixer
===========================================================
Identifier: *spiking_fla_spikegated_mixer*

Paradigm shift
--------------
This block abandons the heavily explored multi-path gating + convolution/
Δ-rule topology.  Instead it introduces **dual-stream modulation** where
*binary spike gates* generated by one spiking projection control the flow of
dense, continuous information produced by a second spiking projection.  A
minimal, purely element-wise interaction is used – avoiding stacked MoE / FIR /
Δ-rule constructs – while still retaining O(N) complexity and strict
causality.

Key principles
~~~~~~~~~~~~~~
1.  **Orthogonal topology** – no attention, no Δ-rule scan, no multi-scale FIR
    branches.  The block relies solely on spike-gated feature mixing followed
    by an (optional) fully-spiking MLP.
2.  **Pure spiking linear usage** – every linear projection is a
    `SpikingLinear`, guaranteeing binary spike inputs for the underlying
    weight matrix as required.
3.  **Explicit spike collection** – spikes from *all* `SpikingLinear` modules
    are gathered and concatenated into a single 1-D tensor `final_spikes`,
    returned by the forward pass.
4.  **Sub-quadratic & causal** – only element-wise operations and per-position
    linear projections are used.  Complexity is O(B·L·D).
5.  **Robust tensor handling** – all reshaping performed via
    `einops.rearrange`, never `.view()`/`.reshape()`, and shapes are inferred
    at runtime.

The resulting architecture offers a brand-new exploration point for combining
spiking and continuous signals without reverting to previously exhausted
attention / Δ-rule / multi-branch gate patterns.
"""
from __future__ import annotations

from typing import Tuple, Optional, Dict, List

import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange

# External utility modules from FLA -------------------------------------------------
from fla.modules import RMSNorm

# -----------------------------------------------------------------------------
# Spiking building blocks (kept exactly as required)
# -----------------------------------------------------------------------------
try:
    from src.models.spike.neuron import registry as neuron_registry
    from src.models.spike.surrogate import piecewise_quadratic_surrogate
except ImportError as exc:  # pragma: no cover
    raise ImportError(
        "Spiking neuron modules (src.models.spike) not found.  "
        "Ensure the neuromorphic package is available." 
    ) from exc

class SpikingLinear(nn.Module):
    """Linear layer preceded by a spiking neuron (MUST remain unmodified)."""

    def __init__(self, linear_layer: nn.Linear, neuron_type: str, surrogate_function):
        super().__init__()
        self.neuron = neuron_registry[neuron_type](surrogate_function=surrogate_function)
        self.linear = linear_layer

    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        x_t = x.transpose(-1, -2)  # (B, L, D) -> (B, D, L)
        spikes_t = self.neuron(x_t)  # binary events
        spikes = spikes_t.transpose(-1, -2)  # back to (B, L, D)
        out = self.linear(spikes)
        return out, spikes  # return both output and the binary spikes

# -----------------------------------------------------------------------------
# Helper Blocks
# -----------------------------------------------------------------------------
class SpikingMLP(nn.Module):
    """Two-layer MLP built entirely from SpikingLinear modules."""

    def __init__(
        self,
        d_model: int,
        d_hidden: int,
        dropout: float = 0.1,
        neuron_type: str = "sdn",
        surrogate_function=piecewise_quadratic_surrogate(),
    ) -> None:
        super().__init__()
        self.fc1 = SpikingLinear(nn.Linear(d_model, d_hidden), neuron_type, surrogate_function)
        self.act = nn.GELU()
        self.dropout = nn.Dropout(dropout)
        self.fc2 = SpikingLinear(nn.Linear(d_hidden, d_model), neuron_type, surrogate_function)

    def forward(self, x: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor]:
        spikes_all: List[torch.Tensor] = []
        x, s1 = self.fc1(x)
        spikes_all.append(s1)
        x = self.act(x)
        x = self.dropout(x)
        x, s2 = self.fc2(x)
        spikes_all.append(s2)
        all_spikes = torch.cat([sp.flatten() for sp in spikes_all])
        return x, all_spikes

# -----------------------------------------------------------------------------
# Main Block – SpikeGatedMixer
# -----------------------------------------------------------------------------
class SpikingFLABlock(nn.Module):
    """Spike-gated feature mixing block (orthogonal to previous DeltaNet family)."""

    def __init__(
        self,
        d_model: int,
        num_heads: int = 1,  # kept for interface compatibility, unused inside
        use_spiking_mlp: bool = True,
        d_ffn_mult: int = 2,
        dropout: float = 0.1,
        prenorm: bool = True,
        neuron_type: str = "sdn",
        **kwargs: Dict,
    ) -> None:
        super().__init__()
        self.prenorm = prenorm
        self.norm_in = RMSNorm(d_model)

        # Dual spiking projections: one produces binary *gates*, the other the
        # *values* to be gated.  Both are per-token and thus causal.
        self.gate_proj = SpikingLinear(nn.Linear(d_model, d_model, bias=False), neuron_type, piecewise_quadratic_surrogate())
        self.value_proj = SpikingLinear(nn.Linear(d_model, d_model, bias=False), neuron_type, piecewise_quadratic_surrogate())

        self.dropout = nn.Dropout(dropout)

        # Optional spiking MLP for further processing
        d_hidden = d_model * d_ffn_mult
        self.use_spiking_mlp = bool(use_spiking_mlp)
        if self.use_spiking_mlp:
            self.mlp = SpikingMLP(d_model, d_hidden, dropout=dropout, neuron_type=neuron_type)
        else:
            # Fallback identity function (no parameters) while respecting output format
            self.mlp = nn.Identity()

        self.norm_mlp = RMSNorm(d_model)
        self.dropout_mlp = nn.Dropout(dropout)

    # ---------------------------------------------------------------------
    def _spike_concat(self, spike_list: List[torch.Tensor]) -> torch.Tensor:
        """Concatenate and flatten spike tensors into 1-D vector (binary)."""
        return torch.cat([s.flatten() for s in spike_list]) if spike_list else torch.empty(0)

    # ---------------------------------------------------------------------
    def forward(self, x: torch.Tensor, **kwargs: Dict):
        """Return tuple: (hidden_out, None, final_spikes)."""
        spike_collector: List[torch.Tensor] = []

        residual = x
        if self.prenorm:
            x = self.norm_in(x)

        # Dual-stream projections ------------------------------------------------
        gates, s_g = self.gate_proj(x)  # (B, L, D)
        values, s_v = self.value_proj(x)
        spike_collector.extend([s_g, s_v])

        # Binary gates modulate continuous values element-wise.
        # Surrogate gradients inside the neuron allow optimisation.
        mixed = gates * values  # (B, L, D), still O(N)

        x = residual + self.dropout(mixed)

        # --------------------- Optional spiking MLP ---------------------
        if self.use_spiking_mlp:
            mlp_in = self.norm_mlp(x) if self.prenorm else x
            mlp_out, s_mlp = self.mlp(mlp_in)
            spike_collector.append(s_mlp)
            x = x + self.dropout_mlp(mlp_out)
        # If Identity(), nothing changed and no extra spikes.

        final_spikes = self._spike_concat(spike_collector)
        return x, None, final_spikes
